const fresh=()=>({version:2,lastTick:Date.now(),decor:[null,null,null,null],levelBase:1,coins:2000,food:0,xp:0,seed:7,selected:0,tutorial:{step:0,plot:0},stats:{pet:0,harvest:0,shear:0},claimed:[],sheep:[{breed:0,name:'아기양',stage:'baby',growth:0,hunger:40,clean:100,wool:0}],plots:[null,null,null,null,null,null]});
let state;try{state=JSON.parse(localStorage.getItem('shipfarm-concept-v1'));if(!state||![1,2].includes(state.version)||!Array.isArray(state.sheep)||!state.sheep.length||!Array.isArray(state.plots)||state.plots.length!==6)state=fresh()}catch{state=fresh()}let tab='farm',toastTimer;const $=s=>document.querySelector(s),img=(key)=>ASSETS[key];
function save(){try{localStorage.setItem('shipfarm-concept-v1',JSON.stringify(state))}catch{$('#saveStatus').textContent='저장 공간을 사용할 수 없어 이번 화면에서만 유지됩니다.'}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function modal(html){$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
const quests=[{id:'pet',title:'양에게 사랑을',detail:'목장의 양을 세 번 쓰다듬어 주세요.',goal:3,reward:150},{id:'harvest',title:'달콤한 첫 수확',detail:'다 자란 작물을 세 번 수확해 주세요.',goal:3,reward:200},{id:'shear',title:'복슬복슬한 선물',detail:'양의 다 자란 털을 깎아 주세요.',goal:1,reward:250}];
function timeLeft(p){let s=Math.max(0,Math.ceil((p.ready-Date.now())/1000));if(!s)return '수확하기';if(s>=3600)return `${Math.floor(s/3600)}시간 ${Math.floor(s%3600/60)}분`;return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
const sheepPos=[[43,59],[58,48],[33,67],[53,74],[62,58],[42,73]],plotPos=[[66,61],[72,65],[61,66],[67,70],[56,71],[62,75]];
function chooseSeed(i){state.seed=i;render();toast(crops[i][0]+' 선택. 목장의 빈 밭에 심어 주세요.')}
function claim(id){const q=quests.find(x=>x.id===id);if(!q||state.claimed.includes(id)||state.stats[id]<q.goal)return;state.claimed.push(id);state.coins+=q.reward;state.xp+=10;render();toast('부탁을 완료했어요. +'+q.reward+' 코인')}
function unlockFlame(){if(!quests.every(q=>state.claimed.includes(q.id))||state.claimed.includes('flame'))return;state.claimed.push('flame');render();toast('플레임램이 해금됐어요! 양 도감에서 만나보세요.')}
function finishCrops(){state.plots.forEach(p=>{if(p)p.ready=Date.now()-1});$('#modal').close();render();toast('심은 작물이 모두 다 자랐어요. (시안 도구)')}
function resetPrompt(){modal('<h2>목장을 처음으로 되돌릴까요?</h2><p>이 브라우저에 저장된 시안의 양·코인·퀘스트 진행이 초기화됩니다.</p><button class="greenbtn" onclick="resetFarm()">초기화하기</button> <button class="action" onclick="document.querySelector(\'dialog\').close()">취소</button>')}
function showNotes(){modal(`<h2>다시 만난 슈가랜드 · 시안 05</h2><p>웹판의 양 수집·농사·돌봄·퀘스트를 중심으로 만든 개인용 인터랙션 시안입니다. 원작의 완전한 복원본은 아닙니다.</p><ul><li>작물 시간·수확량: 옛 웹판 위키 자료 기준.</li><li>양 그림: 메타랜드 공개 도감의 정지 이미지로 외형 비교용. 걷기·먹기 동작은 새로 만든 모션. 명칭 대응은 잠정적입니다.</li><li>배경·아기양·작물 그림과 모션: 시안용으로 새로 제작.</li><li>아기양·성장 튜토리얼, 돌봄 모션과 보상 수치는 체험용 설계. 생활 주기는 시안용이며 시듦·플레이어 간 교역·교배는 미구현.</li><li>NFT·지갑·토큰·레이싱·유료 결제 없음.</li></ul><p><a href="https://blog.naver.com/yoakaori/150132026646" target="_blank" rel="noopener">2012년 웹판 양 상점 자료 ↗</a><br><a href="https://github.com/forkwikiman/enha/blob/master/mirror/쉽팜%20인%20슈가랜드.md" target="_blank" rel="noopener">옛 웹판 위키 보존본 ↗</a><br><a href="https://guide.sheepfarm.io/guide/gameplay/sheep" target="_blank" rel="noopener">외형 참고 이미지 출처 ↗</a></p>`)}
