function babySvg(){return `<svg class="baby-svg" viewBox="0 0 120 110" aria-hidden="true"><g stroke="#8e7e69" stroke-width="2.5" stroke-linejoin="round"><g class="baby-leg a"><path d="M35 70L34 94Q36 99 43 95L46 72" fill="#ecdfc2"/><path d="M34 91L42 92V96L35 97Z" fill="#a18c76"/></g><g class="baby-leg b"><path d="M64 70L66 95Q70 99 76 94L75 71" fill="#e5d4b5"/><path d="M66 91L75 91V96L68 97Z" fill="#a18c76"/></g><path d="M24 54Q7 41 14 35Q24 31 29 44" fill="#faf1da"/><path d="M26 37Q22 25 35 22Q40 11 51 17Q63 8 72 18Q87 15 90 30Q103 34 94 48Q105 60 93 68Q94 80 78 80Q68 91 57 81Q42 87 36 77Q20 81 21 66Q11 54 26 47Z" fill="#fff8e5"/><path d="M26 65Q29 75 40 72Q49 83 58 76Q74 84 81 73Q94 74 92 64" fill="none" stroke="#e4d7b9" stroke-width="5"/><g class="baby-ear"><path d="M78 37Q60 22 62 37Q65 50 81 46" fill="#ecdcbd"/><path d="M77 40L67 35" stroke="#ddb8a2" stroke-width="3"/></g><path d="M85 33Q105 32 107 49Q119 60 108 70Q99 78 85 68Q76 60 81 47Z" fill="#f4e3c4"/><path d="M81 34Q78 22 90 24Q98 19 103 28Q112 31 106 39Q95 45 87 39Z" fill="#fff8e5"/><ellipse class="baby-eye" cx="98" cy="51" rx="3.3" ry="4" fill="#716250" stroke="none"/><circle cx="106" cy="61" r="4" fill="#edc1ae" stroke="none"/><path d="M108 61Q115 61 113 65" fill="none" stroke-width="2"/></g></svg>`}
const tutorialSteps=[['처음 만난 작은 친구','바구니에서 나온 아기양에게 이름을 지어 주세요.'],['따뜻한 첫 인사','아기양을 한 번 쓰다듬어 주세요. 아직 조금 낯을 가리네요.'],['꼬르륵, 우유가 필요해요','우유를 먹이면 아기양이 한 뼘 더 자라요.'],['잘 자라, 작은 솜뭉치','낮잠 재우기를 누르고 잠깐 기다려 주세요. 체험에서는 6초 후 자라요.'],['첫 번째 달콤한 씨앗','화살표가 있는 빈 밭에 캬라멜팝콘을 심어 주세요.'],['곧 수확할 수 있어요','첫 작물은 체험용으로 12초면 자라요. 다 자라면 밭을 눌러 주세요.'],['이제 밥도 잘 먹어요','수확한 먹이를 주세요. 양이 밭 옆으로 걸어가 냠냠 먹어요.'],['복슬복슬, 첫 양털','다 자란 털을 깎아 보세요. 첫 목장 생활이 완성돼요.'],['우리의 목장 이야기가 시작됐어요','씨앗을 심고, 친구를 입양하고, 천천히 목장을 채워 보세요.']];
function tutStep(){return state.tutorial?.step??8}function currentLevel(){return (state.levelBase??10)+Math.floor(state.xp/100)}
function guideBand(){const step=tutStep();if(step>=8)return '';const t=tutorialSteps[step];return `<div class="tutorial-band" aria-live="polite"><div class="guide-portrait">✿</div><div class="tutorial-copy"><small>미셸의 첫 목장 수업</small><strong>${t[0]}</strong><p>${t[1]}</p><div class="tutorial-dots">${Array.from({length:8},(_,i)=>`<i class="${i<=step?'done':''}"></i>`).join('')}</div></div>${step===0?'<button class="greenbtn" onclick="nameBaby()">이름 지어주기</button>':`<span class="tutorial-count">${step+1} / 8</span>`}</div>`}
function nameBaby(){modal(`<div class="welcome-art">${babySvg()}</div><span class="eyebrow">A LITTLE HELLO</span><h2 style="margin-top:8px">우리, 오래오래 함께하자.</h2><p>이 작은 양의 첫 번째 가족이 되어 주세요.<br>어떤 이름으로 불러 줄까요?</p><form id="nameForm"><label for="babyName">아기양 이름</label><input class="name-input" id="babyName" maxlength="12" value="몽실이" autocomplete="off" required><button class="greenbtn" type="submit">우리 목장에 온 걸 환영해</button></form>`);$('#nameForm').onsubmit=e=>{e.preventDefault();const name=$('#babyName').value.trim().slice(0,12);if(!name){$('#babyName').setCustomValidity('이름을 한 글자 이상 적어 주세요.');$('#babyName').reportValidity();return}state.sheep[0].name=name;state.tutorial.step=1;$('#modal').close();render();react(0,'happy',1800);toast(name+'이 우리 목장에 왔어요.')};$('#babyName').oninput=()=>$('#babyName').setCustomValidity('');$('#babyName').focus();$('#babyName').select()}
function sheepArt(s){if(s.stage==='baby')return babySvg();return `<span class="adult-foot a"></span><span class="adult-foot b"></span><span class="adult-foot c"></span><img class="sprite-img" src="${sheepImage(s)}" alt="${breeds[s.breed].name}">`}
function sheepBubble(s,m){if(m?.mode==='sleeping')return 'z z Z';if(m?.mode==='eating')return s.stage==='baby'?'우유 냠냠':'냠냠';if(m?.mode==='happy')return '♥';if(m?.mode==='washing')return '◌';if(m?.mode==='growing')return '✧';if(s.stage==='baby')return s.growth>=65?'졸려요':'♡';return s.wool>=100?'✂':s.hunger<50?'♧':'♡'}
function farmBase(){const s=state.sheep[state.selected],b=breeds[s.breed],baby=s.stage==='baby',step=tutStep();const hint=step===1?'pet':step===2?'milk':step===3?'nap':step===6?'feed':step===7?'shear':'';const action=(k,icon,label,disabled=false)=>`<button class="action ${hint===k?'hint':''} ${k==='shear'?'primary':''}" aria-label="${label}" onclick="care('${k}')" ${disabled?'disabled':''}><em>${icon}</em>${label}</button>`;return `<div class="scene"><div class="world">${backdrop()}<span class="scene-label">♧ &nbsp; 슈가랜드 · 우리집 목장</span>${state.plots.map((p,i)=>`<button class="cropplot ${(step===4||step===5)&&i===(state.tutorial.plot??0)?'tutorial-target':''}" data-plot="${i}" style="left:${plotPos[i][0]}%;top:${plotPos[i][1]}%" onclick="plot(${i})" aria-label="밭 ${i+1}: ${p?crops[p.crop][0]+' '+timeLeft(p):'씨앗 심기'}">${p?plantSvg(p.ready<=Date.now(),p.crop,cropProgress(p)):'<svg viewBox="0 0 70 70"><path d="M4 46L35 31L67 46L35 63Z" fill="#b28c61" stroke="#96744f" stroke-width="2"/><path d="M25 47H45M35 39V55" stroke="#e6d0a7" stroke-width="2"/></svg>'}<span class="timer">${p?timeLeft(p):'+ 씨앗 심기'}</span></button>`).join('')}${state.sheep.map((s,i)=>{const m=getMotion(i);return `<button data-sheep="${i}" class="sheep ${s.stage==='baby'?'baby':''} ${m.mode} ${i===state.selected?'selected':''} ${s.wool===0?'sheared':''} ${s.clean<25?'dirty':''}" style="left:${m.x}%;top:${m.y}%;--face:${m.face};z-index:${Math.round(m.y)}" onpointerenter="pauseSheep(${i})" onclick="selectSheep(${i})" aria-label="${esc(s.name)} 선택"><span class="actor-shadow"></span><span class="bubble">${sheepBubble(s,m)}</span><span class="actor-facing"><span class="actor">${sheepArt(s)}</span></span><span class="name">${esc(s.name)}</span></button>`}).join('')}${Array.from({length:9},(_,i)=>`<i class="sparkle" style="left:${19+i*7}%;top:${30+(i*19)%46}%;animation-delay:-${i}s"></i>`).join('')}<i class="butterfly" style="left:29%;top:64%"></i><i class="butterfly" style="left:70%;top:39%;animation-delay:-8s"></i><span class="map-controls">양들은 스스로 산책해요 · 좁은 화면에서는 옆으로 밀어 보세요</span></div></div>${guideBand()}<div class="actiontray"><div class="selected-info">${baby?`<div class="mini-baby">${babySvg()}</div>`:`<img src="${sheepImage(s)}" alt="">`}<div><h3>${esc(s.name)} <span class="badge ${baby?'baby-pill':''}">${baby?'아기양':b.name}</span></h3><small>${baby?'성장 '+s.growth+'% · '+(s.sleepUntil?'새근새근 자고 있어요':'작은 손길이 필요해요'):'포만감 '+s.hunger+'% · 털 '+s.wool+'%'}</small><div class="track"><i style="width:${baby?s.growth:s.wool}%"></i></div></div></div><div class="actions">${action('pet','♡','쓰다듬기',!!s.sleepUntil)}${baby?action('milk','♧','우유 먹이기',s.growth<25||s.growth>=65||!!s.sleepUntil):action('feed','♧','먹이 주기')}${baby?action('nap','☾','낮잠 재우기',s.growth<65||!!s.sleepUntil):action('wash','♨','씻겨주기')}${!baby?action('shear','✂','털 깎기',s.wool<100):''}</div></div>`}
function renderBase(){state.selected=Math.min(state.selected,state.sheep.length-1);$('#coins').textContent=state.coins.toLocaleString();$('#food').textContent=state.food;$('#xp').textContent=(state.xp%100)+' / 100';$('#level').textContent=currentLevel();$('#xpbar').style.width=(state.xp%100)+'%';$('#flockCount').textContent='양 '+state.sheep.length+' / 6 · 밭 6칸';$('#sidequests').innerHTML=tutStep()<8?`<div class="tutorial-side"><span class="guide-name">미셸의 첫 목장 수업</span><b>${tutorialSteps[tutStep()][0]}</b>${tutorialSteps[tutStep()][1]}<div class="track"><i style="width:${tutStep()/8*100}%"></i></div></div>`:quests.slice(0,2).map(q=>`<button class="quest" onclick="navigate('quests')"><span class="tiny">${state.claimed.includes(q.id)?'완료':'오늘의 부탁'}</span><strong>${q.title}</strong><span>${Math.min(state.stats[q.id],q.goal)} / ${q.goal} · 보상 ${q.reward} 코인</span></button>`).join('');

document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const scene=$('.scene'),scroll=scene?.scrollLeft??sceneScroll;$('#content').innerHTML=tab==='farm'?farm():tab==='sheep'?collection():tab==='crops'?cropShop():tab==='market'?market():tab==='barn'?barn():tab==='village'?village():stories();if($('.scene'))$('.scene').scrollLeft=scroll;save()}
function selectSheep(i){state.selected=i;const m=getMotion(i);if(m.mode==='walking'&&!m.pending){m.mode='idle';m.until=performance.now()+1800;m.route=null}render()}
function navigate(t){if($('.scene'))sceneScroll=$('.scene').scrollLeft;if(tutStep()<8&&t!=='farm'){toast('아기양의 첫 목장 수업을 마치면 다른 메뉴도 열려요.');return}tab=t;render()}
function careBase(kind){const i=state.selected,s=state.sheep[i],step=tutStep();if(step===0)return nameBaby();if(s.sleepUntil)return toast('아기양이 새근새근 자고 있어요.');if(s.stage==='baby'){if(kind==='pet'){s.growth=Math.max(s.growth,25);state.stats.pet++;state.xp+=2;if(step===1)state.tutorial.step=2;render();react(i,'happy',2000);toast(escText(s.name)+'이 손길에 폭 안겼어요.')}else if(kind==='milk'){if(s.growth<25||s.growth>=65)return;s.growth=65;s.hunger=90;if(step===2)state.tutorial.step=3;render();react(i,'eating',3000);toast('우유를 꼴깍꼴깍, 한 뼘 더 자랐어요.')}else if(kind==='nap'){if(s.growth<65)return;s.sleepUntil=Date.now()+6000;save();render();react(i,'sleeping',6500);toast('작은 꿈을 꾸는 중이에요. 잠깐 기다려 주세요.')}return}
if(step<8&&((step===6&&kind!=='feed')||(step===7&&kind!=='shear')||step===4||step===5)){return toast(tutorialSteps[step][1])}
if(kind==='feed'){if(getMotion(i).pending)return toast('먹이를 먹으러 가고 있어요.');if(state.food<5)return toast('먹이가 부족해요. 밭에서 작물을 수확해 주세요.');if(s.hunger===100)return toast('아직 배가 불러요.');state.food-=5;s.hunger=Math.min(100,s.hunger+25);s.wool=step===6?100:Math.min(100,s.wool+25);s.pendingFeed=true;if(step===6)state.tutorial.step=7;render();goToFood(i);toast(s.name+'이 먹이를 먹으러 가요.');return}
if(kind==='pet'){state.stats.pet++;state.xp+=2;render();react(i,'happy',2200);toast(s.name+'이 기분 좋게 메에~ 하고 울어요.');return}
if(kind==='wash'){s.clean=100;render();react(i,'washing',2400);toast(s.name+'이 보송보송해졌어요.');return}
if(kind==='shear'){if(s.wool<100)return;if(getMotion(i).pending||s.pendingFeed)return toast('양이 밥을 다 먹을 때까지 잠깐 기다려 주세요.');state.stats.shear++;s.wool=0;if(step===7)state.coins+=120;else state.woolStock[s.breed]=(state.woolStock[s.breed]??0)+1;state.xp+=8;if(step===7){state.tutorial.step=8;state.coins+=500;state.xp=Math.max(100,state.xp);toast('첫 목장 수업 완료! 축하 선물 500코인을 받았어요.')}else toast(breeds[s.breed].name+' 양털 1묶음을 창고에 보관했어요.');render();react(i,'shearing',2500)}}
function escText(s){return String(s)}
function plot(i){const step=tutStep();if(step<4)return toast('먼저 아기양이 잘 자라도록 돌봐 주세요.');let p=state.plots[i];if(!p){if(step===5||step===6||step===7)return toast(tutorialSteps[step][1]);if(step===4){state.seed=7;state.tutorial.plot=i;state.tutorial.step=5}state.plots[i]={crop:state.seed,plantedAt:Date.now(),ready:Date.now()+(step===4?12:crops[state.seed][2])*1000,tutorial:step===4};toast(crops[state.seed][0]+' 씨앗을 심었어요.');render();return}if(p.ready>Date.now())return toast(crops[p.crop][0]+'가 자라는 중이에요. '+timeLeft(p)+' 남았어요.');state.food+=crops[p.crop][1];state.stats.harvest++;state.xp+=5;state.plots[i]=null;if(step===5)state.tutorial.step=6;toast(crops[p.crop][0]+' 수확! 먹이 +'+crops[p.crop][1]);render()}
function resetFarm(){state=fresh();decorating=false;motion.clear();sceneScroll=170;tab='farm';$('#modal').close();render();toast('작은 아기양과 첫 만남이 시작돼요.')}
function growBabies(){let changed=false;state.sheep.forEach((s,i)=>{if(s.sleepUntil&&Date.now()>=s.sleepUntil){s.stage='adult';s.growth=100;s.wool=50;s.hunger=55;delete s.sleepUntil;if(i===0&&tutStep()===3)state.tutorial.step=4;changed=true;const m=getMotion(i);m.mode='growing';m.until=performance.now()+1800;toast(s.name+'이 자랐어요! 이제 함께 밭을 가꿔요.')}});if(changed)render()}
// Movement stays on the clear grazing lawn, away from the house, pond and crops.
const walkPoints=[[34,57],[43,49],[53,45],[61,48],[56,59],[47,67],[35,65],[42,58],[53,73]], motion=new Map();let sceneScroll=170;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
function getMotion(i){if(!motion.has(i)){const p=sheepPos[i%sheepPos.length];motion.set(i,{x:p[0],y:p[1],face:1,mode:state.sheep[i]?.sleepUntil?'sleeping':'idle',until:performance.now()+1000+i*650,route:null,pending:null})}return motion.get(i)}
function react(i,mode,duration){const m=getMotion(i);if(m.pending&&mode!=='eating')return;m.mode=mode;m.until=performance.now()+duration;m.route=null;syncActor(i,m)}
function goToFood(i){const m=getMotion(i);m.pending='eat';m.route={x:58,y:61};m.mode='walking';m.until=0;if(reducedMotion.matches){m.x=58;m.y=61;arrive(i,m)}syncActor(i,m)}
function arrive(i,m){m.route=null;if(m.pending==='eat'){m.mode='eating';m.until=performance.now()+2200;m.pending='finishing'}else{m.mode=['idle','grazing','idle','sleeping'][Math.floor(Math.random()*4)];m.until=performance.now()+2200+Math.random()*3500}}
function syncActor(i,m){const el=document.querySelector(`[data-sheep="${i}"]`);if(!el)return;const s=state.sheep[i];el.style.left=m.x+'%';el.style.top=m.y+'%';el.style.setProperty('--face',m.face);el.style.zIndex=Math.round(m.y);const cl=`sheep ${s.stage==='baby'?'baby':''} ${m.mode} ${i===state.selected?'selected':''} ${s.wool===0?'sheared':''} ${s.clean<25?'dirty':''}`;if(el.className!==cl)el.className=cl;const bubble=el.querySelector('.bubble');const text=sheepBubble(s,m);if(bubble.textContent!==text)bubble.textContent=text;const effect=el.querySelector('.reaction');if(['happy','washing','growing'].includes(m.mode)&&!reducedMotion.matches){if(!effect){const e=document.createElement('span');e.className='reaction';e.textContent=m.mode==='happy'?'♥':m.mode==='washing'?'◌':'✧';el.append(e)}}else effect?.remove()}
let lastFrame=0;
function animate(now){const dt=Math.min((now-lastFrame)/1000,.08);lastFrame=now;if(!document.hidden){state.sheep.forEach((s,i)=>{const m=getMotion(i);if(s.sleepUntil){m.mode='sleeping';m.route=null;syncActor(i,m);return}if(m.mode==='walking'&&m.route){const dx=m.route.x-m.x,dy=m.route.y-m.y;const dist=Math.hypot(dx,dy),speed=s.stage==='baby'?2.1:3.0;if(dist<.18){arrive(i,m)}else{const step=Math.min(dist,speed*dt);m.x+=dx/dist*step;m.y+=dy/dist*step;if(Math.abs(dx)>.15)m.face=dx>0?1:-1}}else if(now>m.until){if(m.pending==='finishing'){m.pending=null;delete s.pendingFeed;save()}if(!reducedMotion.matches&&!$('#modal').open){const options=walkPoints.filter(p=>Math.hypot(p[0]-m.x,p[1]-m.y)>3&&[...motion.entries()].every(([j,o])=>j===i||Math.hypot((p[0]-o.x)*1.6,p[1]-o.y)>10));const p=options[Math.floor(Math.random()*options.length)];if(p){m.route={x:p[0],y:p[1]};m.mode='walking'}else{m.mode='idle';m.until=now+1500}}else{m.mode='idle';m.until=now+2500}}if(tab==='farm')syncActor(i,m)});if(tab==='farm'&&!reducedMotion.matches){separateSheep(dt);state.sheep.forEach((_,i)=>syncActor(i,getMotion(i)))}}requestAnimationFrame(animate)}
function migrateState(){ensureHomestead();if(state.version===1){state.version=2;state.levelBase=10;state.tutorial={step:8};state.sheep.forEach(s=>{s.stage='adult';s.growth=100})}state.tutorial??={step:8};state.decor??=[null,null,null,null];state.lastTick??=Date.now();state.sheep.forEach(s=>{s.stage??='adult';s.growth??=100;if(s.pendingFeed)delete s.pendingFeed});state.selected=Math.max(0,Math.min(state.selected??0,state.sheep.length-1))}
// Life values are prototype balancing, not recovered original-game formulas.
const LIFE={hungerSeconds:40,cleanSeconds:90,woolSeconds:8,maxOffline:7200};
const decorTypes=[{name:'작은 꽃밭',price:80},{name:'새들의 쉼터',price:140},{name:'버섯 조명',price:120},{name:'목장 벤치',price:180}];
const decorSpots=[[23,61],[45,38],[74,56],[45,77]];let decorating=false,chosenDecor=0,importCandidate=null,lastUiSecond=0;
const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
function advanceLife(now=Date.now()){
 const last=state.lastTick??now;const elapsed=clamp((now-last)/1000,0,LIFE.maxOffline);state.lastTick=Math.max(last,now);
 if(tutStep()<8||!elapsed)return;
 for(const s of state.sheep){if(s.stage!=='adult'||s.sleepUntil)continue;
  const active=Math.max(0,Math.min(elapsed,(s.hunger-15)*LIFE.hungerSeconds,(s.clean-20)*LIFE.cleanSeconds));
  if(!s.pendingFeed)s.wool=clamp(s.wool+active/LIFE.woolSeconds);
  s.hunger=clamp(s.hunger-elapsed/LIFE.hungerSeconds);s.clean=clamp(s.clean-elapsed/LIFE.cleanSeconds);
 }
}
function flockStrip(){return `<div class="flockbar"><span>우리집 친구들</span>${state.sheep.map((s,i)=>`<button class="flockchip ${i===state.selected?'active':''}" onclick="focusSheep(${i})" aria-label="${esc(s.name)} 찾아가기"><img src="${sheepImage(s)}" alt=""><span>${esc(s.name)}</span><i class="status-dot ${(s.hunger<25||s.clean<25)?'needs':''}"></i></button>`).join('')}</div>`}
function focusSheep(i){selectSheep(i);const scene=$('.scene'),world=$('.world');if(scene&&world){scene.scrollLeft=Math.max(0,getMotion(i).x/100*world.clientWidth-scene.clientWidth/2);sceneScroll=scene.scrollLeft}}
function pauseSheep(i){const m=getMotion(i);if(m.mode==='walking'&&!m.pending){m.mode='idle';m.route=null;m.until=performance.now()+1500}}
function lifeHint(s){if(s.stage==='baby')return s.sleepUntil?'낮잠 '+Math.max(0,Math.ceil((s.sleepUntil-Date.now())/1000))+'초 남음':s.growth>=65?'낮잠을 자고 나면 더 자라요.':s.growth>=25?'이제 우유를 먹일 수 있어요.':'쓰다듬어 첫 인사를 해 주세요.';if(s.pendingFeed)return '먹으러 가는 중이에요. 잠깐 기다려 주세요.';if(s.wool>=100)return '털이 다 자랐어요. 깎아 주세요!';if(s.hunger<=15)return '배가 고파 털 성장이 쉬고 있어요.';if(s.clean<=20)return '씻겨주면 털이 다시 자라요.';return '편안하게 쉬는 동안 양털이 자라고 있어요.'}
function updateVitals(){if(tab!=='farm')return;const s=state.sheep[state.selected],baby=s.stage==='baby',summary=$('.selected-info small');if(summary){summary.className='needs-row';summary.innerHTML=baby?`성장 ${Math.round(s.growth)}% · ${s.sleepUntil?'새근새근 자고 있어요':'아기양'}`:`<span class="${s.hunger<25?'low':''}">♧ 포만감 ${Math.round(s.hunger)}%</span><span class="${s.clean<25?'low':''}">◌ 청결 ${Math.round(s.clean)}%</span><span>✂ 털 ${Math.floor(s.wool)}%</span>`}
 const bar=$('.selected-info .track i');if(bar)bar.style.width=(baby?s.growth:s.wool)+'%';const hint=$('.care-state');if(hint)hint.textContent=lifeHint(s);
 const shear=$('[aria-label="털 깎기"]');if(shear)shear.disabled=s.wool<100||!!s.pendingFeed;
 const feed=$('[aria-label="먹이 주기"]');if(feed)feed.disabled=!!s.pendingFeed||s.hunger>99.5;
 const ready=state.plots.filter(p=>p&&p.ready<=Date.now()).length;const status=$('#lifeSummary');if(status)status.textContent=ready?`수확할 작물 ${ready}칸이 기다려요.`:'양도 작물도 천천히 자라는 중이에요.';
}
function render(){ensureProgression();document.body.dataset.light=state.light??'day';const weather=$('.weather');if(weather)weather.textContent=state.light==='night'?'☾ 별빛 · 반딧불이 쉬어 가는 저녁':state.light==='sunset'?'◒ 노을 · 살구빛이 내려앉은 목장':'☀ 맑음 · 달콤한 바람이 부는 오후';advanceLife();renderBase();updateRequestSidebar();const villageView=$('.village-view');if(villageView)villageView.dataset.helpDay=helpDay();if(tab==='farm'){$('.actiontray')?.insertAdjacentHTML('beforebegin',firstSaleGuide());const head=$('.selected-info h3');head?.insertAdjacentHTML('beforeend','<button class="rename-btn" onclick="sheepJournal()" aria-label="선택한 양 수첩">✎</button>');$('.selected-info small')?.insertAdjacentHTML('afterend','<div class="care-state"></div>');updateVitals();updatePlots();updateHarvestButton();} }
function farm(){let html=farmBase();html=html.replace('<div class="scene">',flockStrip()+'<div class="scene">');html=html.replace('<span class="scene-label">',decorLayer()+'<span class="scene-label">');html=html.replace('</div></div>'+guideBand(),'</div></div>'+guideBand()+decorPalette());html+=`<div class="life-bar"><span id="lifeSummary"></span>${tutStep()>=8?'<button class="wool-shortcut" onclick="navigate(\'market\')">양털 창고 '+woolTotal()+'묶음</button><button onclick="plantAll()">빈 밭 모두 심기</button><button id="bulkHarvest" class="bulk-harvest" onclick="harvestAll()">모두 수확</button>':''}<span><b>♧ ${crops[state.seed][0]}</b> · 먹이 ${state.food}개</span>${tutStep()>=8?'<button class="mobile-edit" onclick="toggleDecor()">'+(decorating?'꾸미기 마치기':'목장 꾸미기')+'</button>':'<button onclick="focusTutorial()">지금 할 일 찾기 ↗</button>'}</div>`;return html}
function focusTutorial(){if(tutStep()===0)return nameBaby();if([4,5].includes(tutStep())){const slot=state.tutorial.plot??0,el=$(`[data-plot="${slot}"]`);el?.scrollIntoView({block:'center',inline:'center',behavior:reducedMotion.matches?'instant':'smooth'});el?.focus({preventScroll:true})}else{$('.actiontray')?.scrollIntoView({block:'center',behavior:reducedMotion.matches?'instant':'smooth'});$('.action.hint')?.focus({preventScroll:true})}}
function plantSvg(grown,cropId=0,progress=0){const leaf='<path d="M35 49V25M35 37Q18 25 21 39Q28 43 35 42M35 32Q51 19 49 33Q44 39 35 38" fill="#a5ba65" stroke="#74894e" stroke-width="2"/>';let plant='';
 if(cropId===0)plant=leaf+'<g fill="#96714b" stroke="#73553d" stroke-width="1.5"><rect x="20" y="17" width="10" height="22" rx="5" transform="rotate(-18 25 28)"/><rect x="36" y="9" width="11" height="25" rx="5" transform="rotate(10 41 22)"/></g><path d="M24 21l3 14M40 14l-1 14" stroke="#dab67b" stroke-width="2"/>';
 if(cropId===1||cropId===3)plant=leaf+`<path d="M25 43V17M43 40V11" stroke="#f2ddb2" stroke-width="3"/><circle cx="24" cy="17" r="10" fill="${cropId===1?'#edaab6':'#b9c7da'}" stroke="#b88c8b" stroke-width="1.5"/><circle cx="44" cy="11" r="11" fill="${cropId===1?'#f3cf96':'#e7babf'}" stroke="#b88c8b" stroke-width="1.5"/><path d="M18 18C14 6 35 9 28 21C21 27 19 16 24 15M37 12C33-1 57 2 49 16C40 24 38 7 44 9" stroke="#fff6d9" stroke-width="3" fill="none"/>`;
 if(cropId===2)plant='<path d="M35 49V21M35 37L20 29M35 28L49 20" stroke="#96724e" stroke-width="4"/>'+[[18,25,-25],[34,13,15],[48,25,25],[29,32,-15]].map(([x,y,r])=>`<ellipse cx="${x}" cy="${y}" rx="9" ry="13" transform="rotate(${r} ${x} ${y})" fill="#e6bb63" stroke="#bb944d" stroke-width="1.5"/><path d="M${x-3} ${y-7}l3 12" stroke="#f8d99a" stroke-width="2"/>`).join('');
 if(cropId===4)plant=leaf+'<path d="M17 35L24 8L34 35Q26 42 17 35ZM36 32L47 3L56 32Q47 40 36 32Z" fill="#8b624c" stroke="#74513d" stroke-width="2"/><path d="M24 13L29 33M47 9L51 29" stroke="#b78a67" stroke-width="3"/>';
 if(cropId===5)plant=leaf+[[23,26],[44,16],[40,37]].map(([x,y])=>`<path d="M${x-9} ${y}Q${x} ${y-9} ${x+9} ${y}Q${x+8} ${y+10} ${x} ${y+14}Q${x-8} ${y+9} ${x-9} ${y}Z" fill="#da8c94" stroke="#b8717b" stroke-width="1.5"/><path d="M${x-8} ${y-1}l7-3l2-5l3 5l5 2l-8 3Z" fill="#91ac67"/><g fill="#f7d6a4"><circle cx="${x-4}" cy="${y+4}" r="1"/><circle cx="${x+3}" cy="${y+3}" r="1"/><circle cx="${x}" cy="${y+9}" r="1"/></g>`).join('');
 if(cropId===6)plant='<path d="M35 22Q32 8 42 12" stroke="#7a9454" stroke-width="4" fill="none"/><path d="M34 20Q16 13 14 32Q11 49 34 48Q57 48 57 31Q55 14 37 20Z" fill="#a67b54" stroke="#806043" stroke-width="2"/><path d="M27 21Q18 35 29 46M40 21Q49 35 39 46M34 21V46" fill="none" stroke="#c39c70" stroke-width="3"/>';
 if(cropId===7)plant=leaf+[[23,29],[42,19],[36,37]].map(([x,y])=>`<path d="M${x-6} ${y-1}Q${x-9} ${y-9} ${x-2} ${y-10}Q${x+5} ${y-13} ${x+7} ${y-6}Q${x+14} ${y-3} ${x+8} ${y+3}Q${x+7} ${y+10} ${x} ${y+7}Q${x-9} ${y+9} ${x-8} ${y+2}Z" fill="#fff0cb" stroke="#c9ac77" stroke-width="1.5"/><circle cx="${x}" cy="${y}" r="3" fill="#d6ac62"/>`).join('');
 const scale=grown?1:progress>.5?.72:.45;return `<svg viewBox="0 0 70 70" aria-hidden="true"><path d="M4 46L35 31L67 46L35 63Z" fill="#ba9263" stroke="#92714c" stroke-width="2"/><path d="M10 46L35 35L61 46L35 57Z" fill="#a17a50"/><path d="M19 44l20 10M29 40l22 10" stroke="#bb9261" stroke-width="1.5"/><g transform="translate(${35*(1-scale)} ${49*(1-scale)}) scale(${scale})">${grown||progress>.2?plant:leaf}</g></svg>`}
function cropProgress(p){const start=p.plantedAt??(p.ready-crops[p.crop][2]*1000);return clamp((Date.now()-start)/Math.max(1,p.ready-start),0,1)}
function updatePlots(){if(tab!=='farm')return;document.querySelectorAll('[data-plot]').forEach(el=>{const i=+el.dataset.plot,p=state.plots[i];if(!p){el.classList.remove('ready');return}const ready=p.ready<=Date.now(),progress=cropProgress(p),stage=ready?3:progress>.5?2:progress>.2?1:0;el.classList.toggle('ready',ready);el.querySelector('.timer').textContent=timeLeft(p);el.setAttribute('aria-label',`밭 ${i+1}: ${crops[p.crop][0]} ${timeLeft(p)}`);if(el.dataset.artStage!==String(stage)){el.querySelector('svg').outerHTML=plantSvg(ready,p.crop,progress);el.dataset.artStage=stage}let bar=el.querySelector('.crop-progress');if(!bar){el.insertAdjacentHTML('beforeend','<span class="crop-progress"><i></i></span><span class="plot-name">'+crops[p.crop][0]+'</span>');bar=el.querySelector('.crop-progress')}bar.querySelector('i').style.width=(progress*100)+'%';bar.hidden=ready})}
function cropShop(){return `<div class="view"><h2>달콤한 씨앗 상점</h2><p class="intro">가까운 기다림부터 느긋한 기다림까지, 오늘의 씨앗을 골라 보세요.</p><div class="crop-shop-help"><span>선택한 씨앗 <b>${crops[state.seed][0]}</b><br>빈 밭을 누르면 심어요. 시안에서는 씨앗이 무료예요.</span><button onclick="navigate('farm');focusFirstEmpty()">목장에 심으러 가기 ↗</button></div><table class="crop-list"><thead><tr><th>작물</th><th>수확량</th><th>재배 시간</th><th>지속 시간</th><th>선택</th></tr></thead><tbody>${crops.map((c,i)=>`<tr class="${state.seed===i?'chosen':''}"><td><span class="seed-icon">${plantSvg(true,i)}</span><b>${c[0]}</b></td><td>${c[1]}</td><td>${c[3]}</td><td>${c[4]}</td><td><button onclick="chooseSeed(${i})">${state.seed===i?'선택됨':'선택'}</button></td></tr>`).join('')}</tbody></table></div>`}
function focusFirstEmpty(){const i=state.plots.findIndex(p=>!p);if(i<0)return toast('밭이 모두 차 있어요. 다 자란 작물을 먼저 수확해 주세요.');$(`[data-plot="${i}"]`)?.scrollIntoView({inline:'center',block:'center',behavior:reducedMotion.matches?'instant':'smooth'})}
function decorSvg(id){const art=[`<path d="M8 52L37 36L69 53L39 69Z" fill="#b99264" stroke="#96764f" stroke-width="2"/><path d="M11 49L37 35L65 50L38 63Z" fill="#a6bb74"/>${flower(23,44,'#ebabb0',1.1)}${flower(39,37,'#fff0bd',1.2)}${flower(51,48,'#e9b5c9',1)}`,`<path d="M36 29V69" stroke="#bc9765" stroke-width="7"/><path d="M18 27L37 13L55 29V50L37 57L18 48Z" fill="#ead3a2" stroke="#a48b63" stroke-width="2"/><path d="M11 29L36 7L62 29L54 33L36 18L20 34Z" fill="#c99c87" stroke="#a98773" stroke-width="2"/><circle cx="37" cy="35" r="7" fill="#998267"/><path d="M29 48H47" stroke="#ae8f67" stroke-width="3"/>`,`<path d="M29 41V62Q36 69 42 62V41" fill="#f4e2b5" stroke="#b4a079" stroke-width="2"/><path d="M12 43Q12 13 35 12Q60 17 62 43Q39 54 12 43Z" fill="#dca09c" stroke="#b7837e" stroke-width="2"/><g fill="#fff0d2"><circle cx="25" cy="29" r="5"/><circle cx="45" cy="26" r="5"/><circle cx="50" cy="40" r="4"/></g><ellipse cx="36" cy="59" rx="21" ry="10" fill="#fff1a2" opacity=".18"/>`,`<path d="M13 45L56 32L70 43L27 58Z" fill="#dab682" stroke="#ac8d60" stroke-width="2"/><path d="M17 46V65M59 36V56M28 54V72M67 44V62" stroke="#a68b63" stroke-width="4"/><path d="M12 23L56 10V31L12 44Z" fill="#e4c28c" stroke="#ab8c60" stroke-width="2"/><path d="M15 32L53 21" stroke="#f7dda7" stroke-width="3"/>`];return `<svg viewBox="0 0 80 80" aria-hidden="true"><ellipse cx="40" cy="67" rx="28" ry="9" fill="#66834225"/>${art[id]??''}</svg>`}
function decorLayer(){return (tutStep()>=8?`<button class="map-edit ${decorating?'active':''}" onclick="toggleDecor()">${decorating?'✓ 꾸미기 완료':'✿ 목장 꾸미기'}</button>`:'')+decorSpots.map(([x,y],i)=>{const id=state.decor?.[i];if(id==null&&!decorating)return '';return `<button class="decor-slot ${decorating?'editing':''}" style="left:${x}%;top:${y}%" onclick="placeDecor(${i})" aria-label="장식 자리 ${i+1}${id!=null?': '+decorTypes[id].name:''}" ${decorating?'':'tabindex="-1"'}>${id==null?'<span class="slot-plus">+</span>':decorSvg(id)}</button>`}).join('')}
function decorPalette(){if(!decorating)return '';return `<div class="decor-palette"><span>장식을 고른 뒤 점선 자리를 눌러 주세요.</span>${decorTypes.map((d,i)=>`<button class="decor-choice ${chosenDecor===i?'active':''}" onclick="chooseDecor(${i})">${d.name}<small>${d.price} 코인</small></button>`).join('')}<button class="decor-choice ${chosenDecor===-1?'active':''}" onclick="chooseDecor(-1)">회수하기<small>구입 코인 반환</small></button></div>`}
function toggleDecor(){if(tutStep()<8)return;decorating=!decorating;render();if(decorating)toast('장식을 골라 점선 안에 놓아 보세요.')}
function chooseDecor(i){chosenDecor=i;render()}
function placeDecor(i){if(!decorating||!Number.isInteger(i)||i<0||i>=4)return;state.decor??=[null,null,null,null];const old=state.decor[i];if(old===chosenDecor||(old==null&&chosenDecor===-1))return;const refund=old==null?0:decorTypes[old].price,cost=chosenDecor===-1?0:decorTypes[chosenDecor].price;if(state.coins+refund<cost)return toast('코인이 부족해요.');state.coins+=refund-cost;state.decor[i]=chosenDecor===-1?null:chosenDecor;render();toast(chosenDecor===-1?'장식을 회수하고 코인을 돌려받았어요.':decorTypes[chosenDecor].name+'을 놓았어요.')}
function sheepJournal(){const i=state.selected,s=state.sheep[i];modal(`<div class="journal-head"><img src="${sheepImage(s)}" alt=""><div><span class="eyebrow">MY LITTLE FRIEND</span><h2 style="margin:5px 0">${esc(s.name)}</h2><span class="badge">${s.stage==='baby'?'아기양':breeds[s.breed].name}</span></div></div><div class="journal-stats"><div>포만감<b>${Math.round(s.hunger)}%</b></div><div>청결<b>${Math.round(s.clean)}%</b></div><div>${s.stage==='baby'?'성장':'양털'}<b>${Math.round(s.stage==='baby'?s.growth:s.wool)}%</b></div></div><p>${lifeHint(s)}</p><form id="renameForm"><label for="renameInput">이름 바꾸기</label><input class="name-input" id="renameInput" value="${esc(s.name)}" maxlength="12" required><button class="greenbtn">이름 저장</button></form><p style="font-size:11px">성체는 배부르고 깨끗할 때 털이 자라요. 포만감 15% 이하 또는 청결 20% 이하면 잠시 쉬어요.</p>`);$('#renameForm').onsubmit=e=>{e.preventDefault();const name=$('#renameInput').value.trim().slice(0,12);if(!name){$('#renameInput').setCustomValidity('이름을 입력해 주세요.');$('#renameInput').reportValidity();return}s.name=name;$('#modal').close();render();toast('이제 '+name+'이라고 불러 주세요.')};$('#renameInput').oninput=()=>$('#renameInput').setCustomValidity('')}
function rewardPop(text){if(reducedMotion.matches)return;const anchor=document.querySelector(`[data-sheep="${state.selected}"]`);if(!anchor)return;const r=anchor.getBoundingClientRect(),e=document.createElement('div');e.className='floater';e.textContent=text;e.style.left=(r.left+r.width/2)+'px';e.style.top=(r.top+10)+'px';document.body.append(e);setTimeout(()=>e.remove(),1500)}
function care(kind){advanceLife();const s=state.sheep[state.selected];if(kind==='pet'&&tutStep()>=8&&Date.now()-(s.lastPet??0)<10000){react(state.selected,'happy',1200);toast('기분 좋은 쓰다듬기! 경험치는 잠시 뒤 다시 받을 수 있어요.');return}const beforeXp=state.xp,beforeCoins=state.coins;careBase(kind);if(kind==='pet'&&state.xp>beforeXp){s.lastPet=Date.now();save();rewardPop('♥ +2 경험치')}if(kind==='shear'&&state.xp>beforeXp&&beforeCoins===state.coins)rewardPop('양털 +1 묶음');if(state.coins>beforeCoins)rewardPop('+'+(state.coins-beforeCoins)+' 코인');updateVitals()}
function showSettings(){modal(`<h2>우리 목장 설정</h2><p>같은 브라우저에서는 자동으로 이어져요.<br>다른 기기에서도 이어하려면 목장 파일을 저장해 두세요.</p><div class="settings-grid"><button class="greenbtn" onclick="exportFarm()">목장 파일로 저장</button><button class="action" onclick="importPrompt()">저장한 목장 불러오기</button></div><hr style="border:0;border-top:1px solid #dfd3ba;margin:22px 0"><div class="settings-grid"><button class="action" onclick="chooseLight()">목장 풍경 바꾸기</button><button class="action" onclick="openMilestones()">목장 앨범</button></div><button class="action" onclick="finishCrops()">심은 작물을 수확 가능하게</button><p style="font-size:11px">시안 체험 도구입니다. 일반 작물 시간은 씨앗 상점에 표시돼요.</p><button class="action" onclick="resetPrompt()">아기양 튜토리얼 새로 시작</button><p style="font-size:11px">초기화 전 다시 확인합니다. 기기의 ‘동작 줄이기’ 설정도 지원해요.</p><details><summary style="font-size:12px;cursor:pointer">생활 주기 안내</summary><p>시안에서는 포만감이 40초에 1, 청결이 90초에 1씩 줄고, 배부르고 깨끗한 성체의 털이 8초에 1씩 자라요. 다시 접속하면 최대 2시간의 경과를 반영해요. 양이 사라지거나 죽지는 않아요. 튜토리얼 중에는 이 주기가 멈춰 있어요.</p></details>`)}
function exportFarm(){advanceLife();save();const payload={format:'shipfarm-backup',savedAt:new Date().toISOString(),state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='우리집-목장-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('목장 파일을 저장했어요.')}
function validBackup(raw){const v=raw?.format==='shipfarm-backup'?raw.state:null;const num=(x,max=1e9)=>typeof x==='number'&&Number.isFinite(x)&&x>=0&&x<=max;const pct=x=>num(x,100);if(!v||![1,2].includes(v.version)||!num(v.coins)||!num(v.food)||!num(v.xp)||!Number.isInteger(v.seed)||v.seed<0||v.seed>=8||!Array.isArray(v.sheep)||v.sheep.length<1||v.sheep.length>6||!Array.isArray(v.plots)||v.plots.length!==6)throw Error('목장 파일 형식이나 수치가 올바르지 않아요.');
 if(!v.stats||!['pet','harvest','shear'].every(k=>num(v.stats[k]))||!Array.isArray(v.claimed)||!v.claimed.every(k=>['pet','harvest','shear','flame',...Object.keys(storyDefs)].includes(k)))throw Error('퀘스트 기록이 올바르지 않아요.');
 if(!v.sheep.every(s=>s&&Number.isInteger(s.breed)&&s.breed>=0&&s.breed<breeds.length&&typeof s.name==='string'&&s.name.trim().length>0&&s.name.length<=60&&pct(s.hunger)&&pct(s.clean)&&pct(s.wool)&&(s.stage==null||['baby','adult'].includes(s.stage))&&(s.growth==null||pct(s.growth))&&(s.sleepUntil==null||num(s.sleepUntil,Date.now()+86400000))&&(s.lastPet==null||num(s.lastPet,Date.now()+10000))))throw Error('양의 기록이 올바르지 않아요.');
 if(!v.plots.every(p=>p===null||(p&&Number.isInteger(p.crop)&&p.crop>=0&&p.crop<8&&num(p.ready,Date.now()+7*86400000)&&(p.plantedAt==null||num(p.plantedAt,Date.now()+86400000)))))throw Error('작물 기록이 올바르지 않아요.');
 if(v.tutorial&&(!Number.isInteger(v.tutorial.step)||v.tutorial.step<0||v.tutorial.step>8||(v.tutorial.plot!=null&&(!Number.isInteger(v.tutorial.plot)||v.tutorial.plot<0||v.tutorial.plot>5))))throw Error('튜토리얼 기록이 올바르지 않아요.');
 if(v.decor&&(!Array.isArray(v.decor)||v.decor.length!==4||!v.decor.every(d=>d===null||(Number.isInteger(d)&&d>=0&&d<4))))throw Error('장식 기록이 올바르지 않아요.');
 if(v.orders&&(!Number.isInteger(v.orders.serial)||!num(v.orders.serial)||!Number.isInteger(v.orders.completed)||!num(v.orders.completed)||!Array.isArray(v.orders.entries)||![0,3].includes(v.orders.entries.length)||!v.orders.entries.every(e=>e&&Number.isInteger(e.template)&&e.template>=0&&e.template<orderTemplates.length&&Number.isInteger(e.token)&&num(e.token)&&e.token<=v.orders.serial&&num(e.base))))throw Error('부탁 기록이 올바르지 않아요.');
 if(v.story){if(typeof v.story!=='object'||Array.isArray(v.story))throw Error('이야기 기록이 올바르지 않아요.');for(const id of Object.keys(storyDefs)){const r=v.story[id];if(r&&(!Number.isInteger(r.step)||r.step<0||r.step>3||typeof r.active!=='boolean'||!num(r.base)||(r.step===3&&r.active)))throw Error('이야기 진행 기록이 올바르지 않아요.')}}
 if(v.levelBase!=null&&!num(v.levelBase,1000))throw Error('레벨 기록이 올바르지 않아요.');if(v.lastTick!=null&&!num(v.lastTick,Date.now()+86400000))throw Error('시간 기록이 올바르지 않아요.');
 if(v.tutorial&&v.version===2){const step=v.tutorial.step;if(step<4&&v.sheep[0].stage!=='baby')throw Error('아기양 진행과 성장 기록이 맞지 않아요.');if(step>=4&&step<8&&v.sheep[0].stage!=='adult')throw Error('성장 진행 기록이 맞지 않아요.')}
 validateHomestead(v);const out=JSON.parse(JSON.stringify(v));out.selected=Number.isInteger(v.selected)?clamp(v.selected,0,v.sheep.length-1):0;return out;
}
function importPrompt(){importCandidate=null;modal('<h2>저장한 목장 불러오기</h2><p>먼저 파일을 확인하고, 적용하기 전에 한 번 더 물어볼게요. 현재 목장은 파일로 저장해 두는 것을 권해요.</p><input class="backup-input" id="backupFile" type="file" accept=".json,application/json"><p class="error-text" id="importError" role="status"></p>');$('#backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1000000){$('#importError').textContent='목장 파일은 1MB 이하만 불러올 수 있어요.';return}try{const candidate=validBackup(JSON.parse(await file.text()));importCandidate=candidate;modal(`<h2>이 목장으로 바꿀까요?</h2><p>풀밭 ${candidate.sheep.length}마리 · 쉼터 ${candidate.barn?.sheep.length??0}마리<br>${Math.floor(candidate.coins).toLocaleString()}코인<br>현재 브라우저의 목장 진행을 이 파일로 바꿉니다.</p><button class="greenbtn" onclick="confirmImport()">이 목장 불러오기</button> <button class="action" onclick="document.querySelector('dialog').close()">취소</button>`)}catch(error){$('#importError').textContent='불러오지 못했어요. 올바른 쉽팜 목장 파일인지 확인해 주세요.'}}}
function confirmImport(){if(!importCandidate)return;state=importCandidate;importCandidate=null;motion.clear();decorating=false;tab='farm';migrateState();advanceLife();$('#modal').close();render();growBabies();toast('저장한 목장으로 돌아왔어요.')}
function tickWorld(){advanceLife();updateVitals();updatePlots();updateHarvestButton();refreshNeighborDay();if(Date.now()-lastUiSecond>10000){lastUiSecond=Date.now();save()}}

function refreshNeighborDay(){
 const view=$('.village-view');
 if(tab==='village'&&view&&Number(view.dataset.helpDay)!==helpDay()){
  const focused=document.activeElement;
  const task=focused?.closest('.help-task');
  const index=task?[...document.querySelectorAll('.help-task')].indexOf(task):-1;
  render();
  if(index>=0)document.querySelectorAll('.help-task')[index]?.focus({preventScroll:true});
 }
}
function firstSaleGuide(){
 if(tutStep()<8||state.stats.sold>0||!woolTotal())return '';
 return `<div class="first-sale-guide"><div><strong>첫 양털이 창고에 도착했어요!</strong><p>이제부터 깎은 털은 창고에 모여요. 장터에서 팔아 새 친구를 맞이할 코인을 모아 보세요.</p></div><button class="greenbtn" onclick="navigate('market')">첫 양털 팔러 가기</button></div>`;
}

