let collectionFilter='all';
function ensureProgression(){ensureHomestead();state.orders??={serial:0,completed:0,entries:[]};state.story??={};if(tutStep()>=8&&state.orders.entries.length===0){for(let i=0;i<3;i++)state.orders.entries.push(makeOrder(i))}}
function metric(kind){return kind==='food'?state.food:(state.stats[kind]??0)}
function makeOrder(template){const t=orderTemplates[template];return {template,token:++state.orders.serial,base:t.kind==='food'?0:metric(t.kind)}}
function orderProgress(entry){const t=orderTemplates[entry.template];return Math.min(t.goal,Math.max(0,metric(t.kind)-(t.kind==='food'?0:entry.base)))}
function claimOrder(slot,token){ensureProgression();const entry=state.orders.entries[slot];if(!entry||entry.token!==token)return;const t=orderTemplates[entry.template];if(orderProgress(entry)<t.goal)return toast('부탁을 조금 더 진행해 주세요.');if(t.kind==='food')state.food-=t.goal;state.coins+=t.coins;state.xp+=t.xp;state.orders.completed++;const used=state.orders.entries.filter((_,i)=>i!==slot).map(e=>e.template);let next=(entry.template+3)%orderTemplates.length;while(used.includes(next))next=(next+1)%orderTemplates.length;state.orders.entries[slot]=makeOrder(next);render();toast(`${t.from}의 부탁 완료! +${t.coins} 코인 · +${t.xp} 경험치`)}
function unlockedBreed(i){if(i===0)return true;if(i===1)return currentLevel()>=10;if(i===2)return state.claimed.includes('flame');if(i===3)return state.claimed.includes('angel');if(i===4)return state.claimed.includes('devil');const b=breeds[i];return !!b&&(b.story?state.claimed.includes(b.story):b.level?currentLevel()>=b.level:false)}
function filterCollection(filter){collectionFilter=filter;render()}
function collection(){const open=breeds.filter((_,i)=>unlockedBreed(i)).length;return `<div class="view"><h2>복슬복슬한 친구들</h2><p class="intro">새 친구는 아기양으로 찾아와요. 이야기를 따라 새로운 친구도 만나 보세요.</p><div class="collection-total"><span>만날 수 있는 양 <b>${open} / ${breeds.length}</b></span><span>함께 사는 친구 ${state.sheep.length} / 6</span></div><div class="filter-row">${[['all','모든 친구'],['open','입양 가능'],['locked','아직 만나지 못한 친구']].map(([id,label])=>`<button class="${collectionFilter===id?'active':''}" onclick="filterCollection('${id}')">${label}</button>`).join('')}</div><div class="catalog">${breeds.map((b,i)=>{const open=unlockedBreed(i);if(collectionFilter==='open'&&!open||collectionFilter==='locked'&&open)return '';const count=[...state.sheep,...state.barn.sheep].filter(s=>s.breed===i).length;return `<article class="catalog-item ${open?'':'locked'}"><div class="owned-label">${count?count+'마리와 함께하는 중':open?'새로운 만남을 기다려요':'이야기를 열어 주세요'}</div><img src="${img(b.art)}" alt="${b.name}"><h3>${b.name}</h3><p>${b.condition}</p><button class="${!open?'open-story':''}" onclick="${open?`adopt(${i})`:`unlockInfo(${i})`}">${open?b.price.toLocaleString()+' 코인 · 입양':b.story?'이야기 보러 가기':'잠금 조건 보기'}</button>${b.variants?`<button class="variant-open" onclick="openVariants(${i})">${b.variants.length}가지 색상 보기</button>`:''}${b.prototypePrice?'<p class="cost-note">입양 가격은 시안용 설정</p>':''}</article>`}).join('')}</div></div>`}
function adopt(i,variant=0){if(!Number.isInteger(i)||!breeds[i]||!unlockedBreed(i))return;if(state.sheep.length>=6)return barnFullPrompt();const b=breeds[i],v=b.variants?.[variant];if(!Number.isInteger(variant)||variant<0||(b.variants?variant>=b.variants.length:variant!==0))return;const cost=v?.price??b.price;if(state.coins<cost)return toast('코인이 부족해요. 이웃의 부탁을 완료해 보세요.');state.coins-=cost;state.sheep.push({breed:i,variant,name:b.name+' '+(state.sheep.length+1),stage:'baby',growth:0,hunger:50,clean:100,wool:0});state.selected=state.sheep.length-1;$('#modal').close();toast('새로운 아기양이 목장에 왔어요.');navigate('farm');focusSheep(state.selected);react(state.selected,'happy',2000)}
function unlockInfo(i){const b=breeds[i];if(!b)return;if(i===2||b.story){navigate('quests');document.querySelector('#story-'+b.story)?.scrollIntoView({block:'center',behavior:reducedMotion.matches?'instant':'smooth'});return}modal(`<h2>${b.name}</h2><img src="${img(b.art)}" alt="" style="height:100px"><p>해금 조건: <b>${b.condition}</b></p><p>현재 레벨 ${currentLevel()} · 반복 부탁과 이웃 돕기로 경험치를 모아 보세요.</p>`)}

function storyProgress(id){const rec=state.story[id],def=storyDefs[id];if(!rec||!rec.active||rec.step>=3)return 0;const c=def.chapters[rec.step];return Math.min(c.goal,Math.max(0,metric(c.kind)-(c.kind==='food'?0:rec.base)))}
function openStory(id){ensureProgression();const def=storyDefs[id];if(!def)return;if(!state.claimed.includes('flame'))return toast('먼저 성냥팔이 소녀의 부탁을 마쳐 주세요.');const rec=state.story[id],done=state.claimed.includes(id),step=rec?.step??0,c=def.chapters[Math.min(step,2)];modal(`<div class="journal-head"><img src="${img(def.art)}" alt="${breeds[def.breed].name}"><div><span class="story-modal-progress">CHAPTER ${Math.min(step+1,3)} / 3</span><h2 style="margin:5px 0">${def.title}</h2><span class="badge">${def.npc}</span></div></div><p class="story-quote">“${c.line}”</p><div class="story-goal">${done?'이야기를 마쳤어요. 양 도감에서 새 친구를 만나 보세요.':c.text+(rec?.active?' · '+storyProgress(id)+' / '+c.goal:'')}</div>${done?'<button class="greenbtn" onclick="document.querySelector(\'dialog\').close();navigate(\'sheep\')">양 도감으로</button>':rec?.active?`<button class="greenbtn" onclick="document.querySelector('dialog').close();navigate('farm')">목장으로 돌아가기</button>`:`<button class="greenbtn" onclick="beginChapter('${id}',${step})">이 부탁 맡기</button>`}<p class="story-note">원작 퀘스트 이름을 참고해 새로 쓴 시안 이야기입니다.</p>`)}
function beginChapter(id,expectedStep){const def=storyDefs[id];if(!def||!state.claimed.includes('flame')||state.claimed.includes(id))return;const rec=state.story[id]??{step:0,active:false,base:0};if(rec.active||rec.step!==expectedStep||rec.step>=3)return;const c=def.chapters[rec.step];rec.active=true;rec.base=c.kind==='food'?0:metric(c.kind);state.story[id]=rec;$('#modal').close();render();toast(c.title+' — '+c.text)}
function finishChapter(id,expectedStep){const def=storyDefs[id],rec=state.story[id];if(!def||!rec?.active||rec.step!==expectedStep||rec.step>=3||state.claimed.includes(id))return;const c=def.chapters[rec.step];if(storyProgress(id)<c.goal)return;if(c.kind==='food')state.food-=c.goal;state.coins+=c.coins;state.xp+=c.xp;rec.step++;rec.active=false;rec.base=0;if(rec.step===3){state.claimed.push(id);toast(breeds[def.breed].name+'이 해금됐어요! 양 도감에서 만나 보세요.')}else toast('부탁을 완료했어요. 다음 이야기가 열렸어요.');render()}
function introQuests(){return `<div class="intro-quests">${quests.map(q=>`<article class="quest-card"><div><h3>${q.title}</h3><p>${q.detail} (${Math.min(state.stats[q.id],q.goal)}/${q.goal})</p><div class="meter"><i style="width:${Math.min(state.stats[q.id]/q.goal,1)*100}%"></i></div></div><button class="greenbtn" onclick="claim('${q.id}')" ${state.claimed.includes(q.id)||state.stats[q.id]<q.goal?'disabled':''}>${state.claimed.includes(q.id)?'완료':q.reward+' 코인 받기'}</button></article>`).join('')}<article class="quest-card"><div><span class="badge">첫 번째 연계 이야기</span><h3 style="margin-top:10px">성냥팔이 소녀</h3><p>세 부탁을 마치고 플레임램을 만나 보세요.</p></div><button class="greenbtn" onclick="unlockFlame()" ${state.claimed.includes('flame')||!quests.every(q=>state.claimed.includes(q.id))?'disabled':''}>${state.claimed.includes('flame')?'해금 완료':'양 해금'}</button></article></div>`}
function stories(){ensureProgression();return `<div class="view"><div class="story-intro"><div><h2>마음이 오가는 작은 마을</h2><p>돌봄과 수확이 다음 만남으로 이어져요.</p></div><span class="story-counter">부탁 ${state.orders.completed}번 완료</span></div><h3 class="section-heading">이웃의 부탁<small>완료하면 새로운 부탁이 도착해요.</small></h3><div class="orders-grid">${state.orders.entries.map((entry,i)=>{const t=orderTemplates[entry.template],n=orderProgress(entry);return `<article class="order-card ${n>=t.goal?'ready':''}"><div class="order-stamp"><span>${t.icon}</span><span>FROM. ${t.from}</span></div><h3>${t.title}</h3><p>${t.text}</p><div class="order-progress"><span>${n} / ${t.goal}</span><span>+${t.coins} 코인 · +${t.xp} XP</span></div><button onclick="claimOrder(${i},${entry.token})" ${n<t.goal?'disabled':''}>${t.kind==='food'?'먹이 건네고 완료':'보상 받기'}</button></article>`}).join('')}</div><h3 class="section-heading">새 친구를 만나는 이야기<small>원작 퀘스트를 바탕으로 각색한 체험 이야기</small></h3>${state.claimed.includes('flame')?'<details class="archive"><summary>완료한 첫 목장 이야기 보기</summary>'+introQuests()+'</details>':introQuests()}${Object.entries(storyDefs).map(([id,def])=>{const rec=state.story[id],done=state.claimed.includes(id),available=state.claimed.includes('flame'),step=rec?.step??0,c=def.chapters[Math.min(step,2)],n=storyProgress(id);return `<article class="story-journey ${available?'':'locked'}" id="story-${id}"><img src="${img(def.art)}" alt=""><div><span class="story-kicker">${done?'함께 만든 이야기':available?'세 번의 작은 만남':'성냥팔이 소녀 이후 열려요'}</span><h3>${def.title}</h3><p>${done?breeds[def.breed].name+'을 입양할 수 있어요.':rec?.active?c.text+' · '+n+'/'+c.goal:c.title+' — '+breeds[def.breed].name+'을 만나는 여정'}</p><div class="chapter-dots">${[0,1,2].map(i=>`<i class="${step>i?'complete':''}"></i>`).join('')}</div></div>${done?`<button class="greenbtn" onclick="navigate('sheep')">새 친구 만나기</button>`:rec?.active?`<button class="greenbtn" onclick="finishChapter('${id}',${step})" ${n<c.goal?'disabled':''}>${step===2?'이야기 마치기':'부탁 완료'}</button>`:`<button class="greenbtn" onclick="openStory('${id}')" ${available?'':'disabled'}>${step?'다음 이야기':'이야기 시작'}</button>`}</article>`}).join('')}<p class="story-note">이웃은 혼자서도 진행할 수 있는 NPC입니다. 대사·목표·보상은 이번 시안에서 새로 구성했어요.</p></div>`}
function updateRequestSidebar(){if(tutStep()<8){const b=$('[data-tab="quests"]');if(b)b.textContent='이야기';return}ensureProgression();const ready=state.orders.entries.filter(e=>orderProgress(e)>=orderTemplates[e.template].goal).length;$('#sidequests').innerHTML=`<div class="request-header">이웃의 부탁${ready?` · ${ready}개 완료 가능`:''}</div>`+state.orders.entries.slice(0,2).map(e=>{const t=orderTemplates[e.template],n=orderProgress(e);return `<button class="quest" onclick="navigate('quests')"><span class="tiny">${t.from}${n>=t.goal?'<i class="request-ready"></i>':''}</span><strong>${t.title}</strong><span>${n} / ${t.goal} · ${t.coins} 코인</span></button>`}).join('');const gifts=milestones.filter(m=>!state.album.includes(m.id)&&m.value()>=m.goal).length;$('#sidequests').insertAdjacentHTML('beforeend',`<button class="album-link" onclick="openMilestones()">우리 목장 앨범${gifts?'<i>'+gifts+'</i>':''}</button>`);const b=$('[data-tab="quests"]');if(b)b.innerHTML='이야기'+(ready?'<i class="request-ready"></i>':'')}
function harvestAll(){if(tutStep()<8)return;const ready=state.plots.map((p,i)=>p&&p.ready<=Date.now()?i:-1).filter(i=>i>=0);if(!ready.length)return;const before=state.food;ready.forEach(i=>plot(i));toast(`${ready.length}칸을 수확했어요. 먹이 +${state.food-before}`)}
function updateHarvestButton(){const b=$('#bulkHarvest');if(!b)return;const count=state.plots.filter(p=>p&&p.ready<=Date.now()).length;b.disabled=!count;b.textContent=count?`모두 수확 (${count})`:'모두 수확'}
// Small local separation prevents idle and walking sheep from stacking up.
function separateSheep(dt){const entries=[...motion.entries()];for(let ai=0;ai<entries.length;ai++){for(let bi=ai+1;bi<entries.length;bi++){const [i,a]=entries[ai],[j,b]=entries[bi];if(!state.sheep[i]||!state.sheep[j])continue;let dx=(a.x-b.x)*9.6,dy=(a.y-b.y)*5.4;let d=Math.hypot(dx,dy);const gap=(state.sheep[i].stage==='baby'?31:40)+(state.sheep[j].stage==='baby'?31:40);if(d>=gap)continue;if(d<.1){dx=i<j?1:-1;dy=.5;d=Math.hypot(dx,dy)}const afixed=!!state.sheep[i].sleepUntil||a.pending==='finishing',bfixed=!!state.sheep[j].sleepUntil||b.pending==='finishing';if(afixed&&bfixed)continue;const push=(gap-d)*Math.min(dt*3,.25),factor=afixed||bfixed?1:.5;if(!afixed){a.x+=dx/d*push*factor/9.6;a.y+=dy/d*push*factor/5.4}if(!bfixed){b.x-=dx/d*push*factor/9.6;b.y-=dy/d*push*factor/5.4}for(const m of [a,b]){m.x=clamp(m.x,30,64);m.y=clamp(m.y,m.x<40?54:44,78)}}}}

// Optional save fields preserve compatibility with versions 1 and 2.
const woolPrices=[120,160,180,220,240,300,210,260,230,420];
const barnSizes=[6,12,24],barnCosts=[1200,3500];
const neighbors=[
 {id:'michelle',name:'미셸',subtitle:'작은 꽃길 목장',breed:0,color:'#dce6b2',line:'멀리서도 들리는 방울 소리가 반가워요. 잠깐 쉬었다 가요.',tasks:['꽃밭에 물 주기','아기양 쓰다듬기','울타리 손보기']},
 {id:'kelly',name:'켈리',subtitle:'달콤한 과자 목장',breed:1,color:'#f3d7bd',line:'갓 구운 과자 냄새가 나죠? 함께 돌보니 하루가 더 달콤해요.',tasks:['간식 바구니 채우기','양털 바구니 정리','밭의 잡초 뽑기']},
 {id:'katie',name:'케이티',subtitle:'바람 부는 바닷가 목장',breed:6,color:'#cce7df',line:'바다에서 온 친구들이에요. 조개껍질 소리를 들려줄까요?',tasks:['조개 길 쓸기','물통 채우기','낮잠 자리 정리']}
];
let villageSelected=0;
function ensureHomestead(){
 state.woolStock??=[];while(state.woolStock.length<breeds.length)state.woolStock.push(0);
 state.barn??={level:0,sheep:[]};state.neighborHelp??={};state.stats.help??=0;state.stats.sold??=0;
 state.album??=[];state.discovered??=[];state.nextSheepId??=1;
 const all=[...state.sheep,...state.barn.sheep],used=new Set();
 for(const s of all){if(!Number.isSafeInteger(s.uid)||s.uid<1||used.has(s.uid))s.uid=state.nextSheepId++;used.add(s.uid);state.nextSheepId=Math.max(state.nextSheepId,s.uid+1);if(!state.discovered.includes(s.breed))state.discovered.push(s.breed)}
}
function validateHomestead(v){
 const uint=(n,max=1e9)=>Number.isSafeInteger(n)&&n>=0&&n<=max;
 if(v.woolStock!=null&&(!Array.isArray(v.woolStock)||v.woolStock.length>breeds.length||!v.woolStock.every(n=>uint(n))))throw Error('양털 창고 기록이 올바르지 않아요.');
 if(v.stats&&['help','sold'].some(k=>v.stats[k]!=null&&!uint(v.stats[k])))throw Error('마을 활동 기록이 올바르지 않아요.');
 if(v.barn!=null){const b=v.barn;if(!b||!uint(b.level,2)||!Array.isArray(b.sheep)||b.sheep.length>barnSizes[b.level])throw Error('쉼터 기록이 올바르지 않아요.');
  for(const s of b.sheep){if(!s||!uint(s.breed,breeds.length-1)||typeof s.name!=='string'||!s.name.trim()||s.name.length>60||!['baby','adult'].includes(s.stage)||!['growth','hunger','clean','wool'].every(k=>typeof s[k]==='number'&&Number.isFinite(s[k])&&s[k]>=0&&s[k]<=100)||s.sleepUntil||s.pendingFeed||(s.lastPet!=null&&(!Number.isFinite(s.lastPet)||s.lastPet<0||s.lastPet>Date.now()+10000)))throw Error('쉼터 친구 기록이 올바르지 않아요.')}
 }
 if(v.nextSheepId!=null&&!uint(v.nextSheepId))throw Error('친구 번호가 올바르지 않아요.');
 for(const s of [...v.sheep,...(v.barn?.sheep??[])]){if(s.variant!=null&&(!uint(s.variant)||s.variant>=(breeds[s.breed]?.variants?.length??1)))throw Error('양의 색상 기록이 올바르지 않아요.')}
 const ids=[...v.sheep,...(v.barn?.sheep??[])].map(s=>s.uid).filter(x=>x!=null);if(ids.some(x=>!uint(x)||x===0)||new Set(ids).size!==ids.length)throw Error('친구 기록이 중복됐어요.');
 if(v.neighborHelp!=null){if(typeof v.neighborHelp!=='object'||Array.isArray(v.neighborHelp))throw Error('이웃 기록이 올바르지 않아요.');for(const [key,day] of Object.entries(v.neighborHelp)){if(!neighbors.some(n=>[0,1,2].some(i=>key===n.id+':'+i))||!uint(day,1000000))throw Error('이웃 방문 기록이 올바르지 않아요.')}}
 if(v.album!=null&&(!Array.isArray(v.album)||!v.album.every(id=>milestones.some(m=>m.id===id))||new Set(v.album).size!==v.album.length))throw Error('앨범 기록이 올바르지 않아요.');
 if(v.discovered!=null&&(!Array.isArray(v.discovered)||!v.discovered.every(n=>uint(n,breeds.length-1))))throw Error('도감 기록이 올바르지 않아요.');
 if(v.light!=null&&!['day','sunset','night'].includes(v.light))throw Error('목장 풍경 설정이 올바르지 않아요.');
}
function woolTotal(){return state.woolStock.reduce((a,b)=>a+b,0)}
function market(){const total=woolTotal(),value=state.woolStock.reduce((n,q,i)=>n+q*woolPrices[i],0);return `<div class="view"><div class="market-banner"><div><span class="eyebrow">SUGARLAND WOOL MARKET</span><h2>폭신한 양털 장터</h2><p>정성껏 돌본 만큼, 바구니에 차곡차곡.</p></div><div class="wool-basket" aria-hidden="true">♧<span>WOOL</span></div></div><div class="store-summary"><div>창고에 보관 중 <b>${total}묶음</b><small>모두 팔면 ${value.toLocaleString()} 코인</small></div><button class="greenbtn" onclick="sellAllWool()" ${total?'':'disabled'}>양털 모두 판매</button></div>${total?'':'<div class="empty-note">다 자란 양의 털을 깎으면 이곳에 모여요.<br>종류마다 다른 양털을 모으고 판매해 보세요. <button onclick="navigate(\'farm\')">목장으로 ↗</button></div>'}<div class="wool-grid">${breeds.map((b,i)=>`<article class="wool-card ${(state.woolStock[i]??0)?'stocked':''}"><img src="${img(b.art)}" alt=""><div><h3>${b.name} 양털</h3><p>1묶음 ${woolPrices[i]} 코인</p><strong>${state.woolStock[i]??0}묶음 보관</strong><div class="sale-actions"><button onclick="sellWool(${i},1)" ${state.woolStock[i]>0?'':'disabled'}>1묶음 판매</button><button onclick="sellWool(${i},5)" ${state.woolStock[i]>=5?'':'disabled'}>5묶음</button></div></div></article>`).join('')}</div><p class="story-note">첫 튜토리얼 양털은 바로 정산됩니다. 이후 양털은 창고에 저장돼요. 판매 가격은 시안용이며 다른 플레이어와 거래하지 않습니다.</p></div>`}
function sellWool(i,amount){if(tutStep()<8||!Number.isInteger(i)||!breeds[i]||!Number.isInteger(amount)||amount<1||state.woolStock[i]<amount)return;state.woolStock[i]-=amount;const earned=woolPrices[i]*amount;state.coins+=earned;state.stats.sold+=amount;render();toast(`양털 ${amount}묶음을 팔았어요. +${earned.toLocaleString()} 코인`)}
function sellAllWool(){if(tutStep()<8)return;const amount=woolTotal();if(!amount)return;const earned=state.woolStock.reduce((n,q,i)=>n+q*woolPrices[i],0);state.woolStock.fill(0);state.coins+=earned;state.stats.sold+=amount;render();toast(`양털 ${amount}묶음 판매! +${earned.toLocaleString()} 코인`)}
function barnFullPrompt(){modal('<h2>풀밭에 친구들이 가득해요.</h2><p>친구 한 마리를 쉼터로 보내면 새 아기양을 맞이할 수 있어요. 쉼터에서도 이름과 성장 기록이 그대로 남아요.</p><button class="greenbtn" onclick="document.querySelector(\'dialog\').close();navigate(\'barn\')">쉼터로 가기</button>')}
function barnCard(s,resting){return `<article class="barn-card"><div class="barn-portrait">${s.stage==='baby'?babySvg():`<img src="${sheepImage(s)}" alt="">`}<span class="badge">${s.stage==='baby'?'아기양':breeds[s.breed].name}</span></div><h3>${esc(s.name)}</h3><p>${s.stage==='baby'?'성장 '+Math.round(s.growth)+'%':'포만감 '+Math.round(s.hunger)+'% · 털 '+Math.floor(s.wool)+'%'}</p><button onclick="${resting?'returnFromBarn':'restInBarn'}(${s.uid})" ${!resting&&(state.sheep.length===1||s.sleepUntil||s.pendingFeed||state.barn.sheep.length>=barnSizes[state.barn.level])?'disabled':''}>${resting?'풀밭으로 데려오기':'쉼터에서 쉬기'}</button></article>`}
function barn(){return `<div class="view"><div class="barn-banner"><span class="eyebrow">A COZY PLACE TO REST</span><h2>포근한 친구들의 쉼터</h2><p>잠시 쉬는 친구도, 오래 함께한 친구도 소중하게.</p></div><div class="store-summary"><div>쉼터 <b>${state.barn.sheep.length} / ${barnSizes[state.barn.level]}마리</b><small>쉼터에서는 포만감·청결·성장이 멈춰요.</small></div>${state.barn.level<2?`<button class="greenbtn" onclick="expandBarnPrompt()">${barnSizes[state.barn.level+1]}자리로 넓히기 · ${barnCosts[state.barn.level].toLocaleString()} 코인</button>`:'<span class="badge">넉넉한 쉼터 완성</span>'}</div><h3 class="section-heading">풀밭에서 노는 친구들 <small>${state.sheep.length} / 6마리 · 한 마리는 풀밭에 남아 있어요.</small></h3><div class="barn-grid">${state.sheep.map(s=>barnCard(s,false)).join('')}</div><h3 class="section-heading">쉼터에서 쉬는 친구들</h3>${state.barn.sheep.length?`<div class="barn-grid">${state.barn.sheep.map(s=>barnCard(s,true)).join('')}</div>`:'<div class="empty-note">아직 쉬고 있는 친구가 없어요.<br>풀밭이 가득 차면 이곳에서 편안히 쉬게 해 주세요.</div>'}<p class="story-note">먹는 중이거나 낮잠으로 자라는 아기양은 돌봄을 마친 뒤 옮길 수 있어요. 양을 되팔거나 없애지 않습니다.</p></div>`}
function settleMovingFlock(){for(const s of state.sheep)delete s.pendingFeed;motion.clear()}
function restInBarn(uid){if(tutStep()<8)return;advanceLife();const i=state.sheep.findIndex(s=>s.uid===uid),s=state.sheep[i];if(!s||state.sheep.length<=1||s.sleepUntil||s.pendingFeed||state.barn.sheep.length>=barnSizes[state.barn.level])return;state.barn.sheep.push(state.sheep.splice(i,1)[0]);state.selected=clamp(state.selected,0,state.sheep.length-1);settleMovingFlock();render();toast(s.name+'이 포근한 쉼터에서 쉬어요.')}
function returnFromBarn(uid){if(tutStep()<8)return;const i=state.barn.sheep.findIndex(s=>s.uid===uid),s=state.barn.sheep[i];if(!s)return;if(state.sheep.length>=6){modal(`<h2>${esc(s.name)}과 교대할 친구</h2><p>풀밭의 친구 한 마리와 자리를 바꿔요. 두 친구의 기록은 그대로예요.</p><div class="swap-list">${state.sheep.map(other=>`<button class="action" onclick="swapBarn(${uid},${other.uid})" ${other.pendingFeed||other.sleepUntil?'disabled':''}>${esc(other.name)} ↔ ${esc(s.name)}</button>`).join('')}</div>`);return}advanceLife();state.sheep.push(state.barn.sheep.splice(i,1)[0]);state.selected=state.sheep.length-1;settleMovingFlock();navigate('farm');focusSheep(state.selected);toast(s.name+'이 다시 풀밭으로 나왔어요.')}
function swapBarn(restUid,fieldUid){if(tutStep()<8)return;const ri=state.barn.sheep.findIndex(s=>s.uid===restUid),fi=state.sheep.findIndex(s=>s.uid===fieldUid);if(ri<0||fi<0||state.sheep[fi].pendingFeed||state.sheep[fi].sleepUntil)return;advanceLife();[state.sheep[fi],state.barn.sheep[ri]]=[state.barn.sheep[ri],state.sheep[fi]];state.selected=fi;settleMovingFlock();$('#modal').close();navigate('farm');focusSheep(fi);toast('친구들이 자리를 바꿨어요.')}
function expandBarnPrompt(){const lv=state.barn.level;if(lv>=2)return;modal(`<h2>쉼터를 더 넓힐까요?</h2><p>${barnSizes[lv]}자리 → ${barnSizes[lv+1]}자리<br>${barnCosts[lv].toLocaleString()} 코인으로 더 많은 친구가 쉬어 갈 수 있어요.</p><button class="greenbtn" onclick="expandBarn(${lv})">쉼터 넓히기</button>`)}
function expandBarn(expected){if(tutStep()<8||state.barn.level!==expected||expected>=2)return;const cost=barnCosts[expected];if(state.coins<cost)return toast('코인이 부족해요. 양털을 팔거나 부탁을 완료해 보세요.');state.coins-=cost;state.barn.level++;$('#modal').close();render();toast('쉼터가 '+barnSizes[state.barn.level]+'자리로 넓어졌어요!')}
function helpDay(now=Date.now()){return Math.floor((now+9*3600000)/86400000)}
function helpedToday(n,i){return (state.neighborHelp[n.id+':'+i]??-1)>=helpDay()}
function village(){const n=neighbors[villageSelected],done=n.tasks.filter((_,i)=>helpedToday(n,i)).length;return `<div class="view village-view"><h2>작은 길로 이어진 이웃 마을</h2><p class="intro">오늘은 누구의 목장에 놀러 갈까요?</p><div class="neighbor-tabs">${neighbors.map((n,i)=>`<button class="${villageSelected===i?'active':''}" onclick="visitNeighbor(${i})"><img src="${img(breeds[n.breed].art)}" alt=""><span>${n.name}<small>${n.subtitle}</small></span></button>`).join('')}</div><div class="neighbor-scene" style="--neighbor-color:${n.color}"><div class="neighbor-sign">${n.subtitle}<small>${n.name}의 목장</small></div><svg class="neighbor-land" viewBox="0 0 700 300" aria-hidden="true"><ellipse cx="350" cy="236" rx="265" ry="55" fill="#b7b488" opacity=".25"/><path d="M70 180L355 65L645 171V206L356 282L70 215Z" fill="#d6ad7c"/><path d="M70 180L355 65L645 171L356 249Z" fill="${n.color}" stroke="#abb583" stroke-width="3"/><path d="M160 166L335 104L407 130L230 195Z" fill="#eee0bd"/>${candyTree(160,140,.7,villageSelected===1?'pink':'green')}${candyTree(537,156,.65,'green')}${cookieFence(405,204,6,28,-10)}${flower(320,206,'#f4b9c5',1.2)}${flower(490,156,'#fff0bc',1.3)}</svg><img class="neighbor-sheep ns-one" src="${img(breeds[n.breed].art)}" alt="${n.name}의 양"><img class="neighbor-sheep ns-two" src="${img(breeds[0].art)}" alt="낮잠 자는 양"><span class="neighbor-welcome">“${n.line}”</span></div><div class="neighbor-heading"><h3>오늘의 작은 도움</h3><span>${done} / 3 완료 · 한국 시간 자정에 새로 열려요.</span></div><div class="neighbor-tasks">${n.tasks.map((t,i)=>`<button class="help-task ${helpedToday(n,i)?'done':''}" onclick="helpNeighbor(${villageSelected},${i})" ${helpedToday(n,i)?'disabled':''}><span>${['✿','♡','♧'][i]}</span><strong>${t}</strong><small>${helpedToday(n,i)?'고마워요! 내일 또 만나요.':'+80 코인 · +12 경험치'}</small></button>`).join('')}</div><p class="story-note">혼자서도 방문하는 NPC 이웃입니다. 실제 이용자의 목장이 아니며, 도움 보상은 기기의 날짜를 기준으로 저장됩니다.</p></div>`}
function visitNeighbor(i){if(!neighbors[i])return;villageSelected=i;render()}
function helpNeighbor(ni,ti){if(tutStep()<8||!Number.isInteger(ni)||!Number.isInteger(ti))return;const n=neighbors[ni];if(!n||!n.tasks[ti]||helpedToday(n,ti))return;state.neighborHelp[n.id+':'+ti]=helpDay();state.stats.help++;state.coins+=80;state.xp+=12;render();toast(n.name+'이 고마움을 전했어요. +80 코인 · +12 경험치')}
function plantAll(){if(tutStep()<8)return;let count=0;const now=Date.now();state.plots.forEach((p,i)=>{if(!p){state.plots[i]={crop:state.seed,plantedAt:now,ready:now+crops[state.seed][2]*1000};count++}});if(!count)return toast('빈 밭이 없어요. 다 자란 작물을 먼저 수확해 주세요.');render();toast(crops[state.seed][0]+' 씨앗을 '+count+'칸에 심었어요.')}
function chooseLight(){modal(`<h2>오늘의 목장 풍경</h2><p>가장 좋아하는 시간에 머물러 보세요.</p><div class="light-choices">${[['day','☀','햇살 가득한 낮'],['sunset','◒','살구빛 노을'],['night','☾','반짝이는 저녁']].map(([id,icon,name])=>`<button class="action ${state.light===id?'chosen':''}" onclick="setLight('${id}')"><b>${icon}</b>${name}</button>`).join('')}</div>`)}
function setLight(id){if(!['day','sunset','night'].includes(id))return;state.light=id;$('#modal').close();render();toast('목장에 새로운 빛이 내려앉았어요.')}
const milestones=[
 {id:'first',title:'작은 첫걸음',text:'아기양 첫 목장 수업 완료',goal:1,value:()=>tutStep()>=8?1:0,coins:200,xp:20},
 {id:'harvester',title:'달콤한 수확 바구니',text:'작물 10번 수확',goal:10,value:()=>state.stats.harvest,coins:300,xp:40},
 {id:'shepherd',title:'폭신한 손길',text:'양털 10번 수확',goal:10,value:()=>state.stats.shear,coins:500,xp:60},
 {id:'neighbor',title:'이웃집 단골손님',text:'이웃 돕기 9번',goal:9,value:()=>state.stats.help,coins:400,xp:50},
 {id:'trader',title:'첫 단골 거래',text:'양털 20묶음 판매',goal:20,value:()=>state.stats.sold,coins:700,xp:90},
 {id:'friends',title:'다섯 가지 복슬복슬',text:'서로 다른 양 5종과 만나기',goal:5,value:()=>state.discovered.length,coins:1200,xp:100},
 {id:'letter',title:'마음이 쌓인 우편함',text:'반복 부탁 20번 완료',goal:20,value:()=>state.orders.completed,coins:1000,xp:100},
 {id:'home',title:'누구에게나 쉴 자리',text:'쉼터를 24자리까지 넓히기',goal:2,value:()=>state.barn.level,coins:800,xp:80}
];
function openMilestones(){ensureProgression();modal(`<h2>우리 목장 앨범</h2><p>함께 쌓은 작은 순간들을 모아 두었어요.</p><div class="album-list">${milestones.map(m=>{const done=state.album.includes(m.id),n=Math.min(m.goal,m.value());return `<article><div><strong>${m.title}</strong><small>${m.text} · ${n}/${m.goal}</small><small>+${m.coins} 코인 · +${m.xp} 경험치</small></div><button class="greenbtn" onclick="claimMilestone('${m.id}')" ${done||n<m.goal?'disabled':''}>${done?'간직했어요':'선물 받기'}</button></article>`}).join('')}</div>`)}
function claimMilestone(id){const m=milestones.find(m=>m.id===id);if(!m||state.album.includes(id)||m.value()<m.goal)return;state.album.push(id);state.coins+=m.coins;state.xp+=m.xp;render();openMilestones();toast('소중한 순간을 앨범에 담았어요. +'+m.coins+' 코인')}
