function sheepImage(s){const b=breeds[s.breed];return img(b.variants?.[s.variant??0]?.art??b.art)}
function sheepColor(s){return breeds[s.breed].variants?.[s.variant??0]?.name??''}
function openVariants(i){const b=breeds[i];if(!b?.variants)return;modal(`<h2>${b.name} · 색상 고르기</h2><p>같은 종류에도 저마다 다른 빛깔이 있어요. 아기양은 자라면서 고른 색상이 나타납니다.</p><div class="variant-grid">${b.variants.map((v,vi)=>`<article><img src="${img(v.art)}" alt="${v.name} ${b.name}"><strong>${v.name}</strong><small>${v.price.toLocaleString()} 코인</small><button class="greenbtn" onclick="adopt(${i},${vi})" ${unlockedBreed(i)?'':'disabled'}>${unlockedBreed(i)?'이 색으로 입양':'아직 잠겨 있어요'}</button></article>`).join('')}</div>`)}
function backdrop(){let html=backdropBase();const light=state.light??'day';if(light==='day')return html;
 const palette=light==='night'?{'#dceccf':'#344961','#f3eed6':'#85939b','#c6dab7':'#50647a','#e8edd6':'#708293','#fffdf0':'#a7b8c6','#c9dc92':'#a5bb86','#bad181':'#91ad76','#a9c477':'#7e9c69','#98bab3':'#ffe5a0','#a7c4b7':'#ffe5a0'}:{'#dceccf':'#f2bca6','#f3eed6':'#f5e1c0','#c6dab7':'#dfad9f','#e8edd6':'#f5d1b6','#fffdf0':'#fff0d6','#98bab3':'#f5db9f'};
 html=html.replace(/#[0-9a-f]{6}/g,c=>palette[c]??c);
 if(light==='night'){const stars=Array.from({length:18},(_,i)=>`<circle cx="${40+(i*173)%880}" cy="${14+(i*31)%80}" r="${i%3?1.2:2}" fill="#fff2c9" opacity=".75"/>`).join('');html=html.replace('<ellipse cx="477"',`<g>${stars}<path d="M830 20A21 21 0 1 0 851 49A23 23 0 0 1 830 20Z" fill="#fff0bd"/></g><ellipse cx="477"`)}return html;
}

document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));$('#brandSheep').src=img('Plain_White');$('#noteSheep').src=img('Marshmallow_Chantilly');
window.addEventListener('resize',()=>requestAnimationFrame(()=>{const scene=$('.scene'),world=$('.world');if(scene&&world){scene.scrollLeft=Math.max(0,getMotion(state.selected).x/100*world.clientWidth-scene.clientWidth/2);sceneScroll=scene.scrollLeft}}));
migrateState();setInterval(growBabies,300);requestAnimationFrame(animate);

setInterval(tickWorld,1000);render();
window.addEventListener('pagehide',()=>{advanceLife();save()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){advanceLife();growBabies();updateVitals();updatePlots();refreshNeighborDay();save()}});
reducedMotion.addEventListener('change',()=>{if(reducedMotion.matches)motion.forEach((m,i)=>{if(m.pending==='eat'){m.x=58;m.y=61;arrive(i,m)}else if(m.mode==='walking'){m.route=null;m.mode='idle';m.until=performance.now()+2500}syncActor(i,m)})});
